<?php require __DIR__ . '/../app/bootstrap.php'; require_once APP_ROOT . '/catalog.php'; $pageTitle='Votre panier · L’Horloger'; require APP_ROOT . '/templates/store-header.php'; ?>
<main class="container cart-page"><p class="eyebrow">Panier</p><h1>Vos montres sélectionnées.</h1><div id="cart-lines" class="cart-lines"></div><div id="cart-empty" class="success" hidden><h2>Votre panier est vide.</h2><p>Découvrez la collection pour choisir votre montre.</p><a class="button" href="<?= e(url('/catalog.php')) ?>">Voir les montres</a></div><div id="cart-total" class="cart-total" hidden><strong>Total à la réception</strong><strong id="cart-total-value"></strong></div><a id="cart-checkout" class="button" href="<?= e(url('/checkout.php')) ?>" hidden>Passer la commande</a></main><script>const products=<?= json_encode(catalog(), JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES) ?>;const lines=LHorlogerCart.read(),box=document.getElementById('cart-lines'),total=lines.reduce((sum,line)=>sum+(products[line.slug]?.price||0)*line.quantity,0);const fmt=n=>new Intl.NumberFormat('fr-FR').format(n)+' FCFA';box.innerHTML=lines.map((line,index)=>{const p=products[line.slug];if(!p)return '';return `<article class="cart-line"><img src="<?= e(url('/')) ?>${p.image}" alt=""><div><strong>${p.name}</strong><p>${line.variant||Object.keys(p.variants)[0]} · Quantité ${line.quantity}</p><b>${fmt(p.price*line.quantity)}</b></div><button type="button" data-remove="${index}">Retirer</button></article>`}).join('');document.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{LHorlogerCart.remove(Number(b.dataset.remove));location.reload()});document.getElementById('cart-empty').hidden=lines.length>0;document.getElementById('cart-total').hidden=lines.length===0;document.getElementById('cart-checkout').hidden=lines.length===0;document.getElementById('cart-total-value').textContent=fmt(total);</script><?php require APP_ROOT . '/templates/store-footer.php'; ?>
